#!/usr/bin/env python3
"""Product-grade read-only UI for Orchestra telemetry.

This is a presentation layer over the canonical dashboard fold. It imports the
existing read/validation/cache implementation and never mutates telemetry.
"""

from __future__ import annotations

import argparse
import html
import http.server
import json
from pathlib import Path
import sys
from typing import Any
import webbrowser

try:
    import orchestra_dashboard as core
except ModuleNotFoundError:
    from scripts import orchestra_dashboard as core  # type: ignore


PRODUCT_UI_VERSION = "2.0"


def _json_for_html(value: Any) -> str:
    return json.dumps(value, ensure_ascii=True, sort_keys=True, separators=(",", ":")).replace("</", "<\\/")


def build_html(snapshot: dict[str, Any], *, live: bool) -> str:
    payload = _json_for_html(snapshot)
